INSERT INTO `Bitacoras` VALUES (1,'Visita de levantamiento','Levantamiento','[\"Daniel Badilla\",\"Sebastian Aviles\"]','2025-10-22','2025-10-22 13:00:00','2025-10-22 15:00:00','Jr6YId6aasUp','xiT-oEgcwH2c',14,14,'[]','[]',0,NULL,'2025-10-22 15:53:08','2025-10-22 15:53:08'),(2,'Visita Rutinaria','Se realiza una visita rutinaria en el cual se revisaron problemas en la recepción, además de problemas con equipos en la oficina frente a la recepción en donde el equipo de Leonardo Valdés se encuentra muy lento debido a la antiguedad del mismo, además de otro equipo que requiere una ampliación de memoria Ram','[\"Daniel Badilla\",\"Sebastian Aviles\"]','2025-10-22','2025-10-22 14:46:00','2025-10-22 15:23:00','iyRcBmhHDn7Y','eE6mD9F9TyCD',24,24,'[]','[]',0,NULL,'2025-10-22 17:20:14','2025-10-22 17:20:14'),(3,'Visita Rutinaria','Se realiza visita rutinaria se supervisa los equipos y conexiones, no se encuentran con novedad. Se recibe 8 Discos Duros y 1 iMAC con cargador. Registro de equipos e impresoras adjuntando archivos para respaldo.','[\"Daniel Badilla\"]','2025-10-28','2025-10-28 14:50:00','2025-10-28 15:01:00','IlOdvZhddCeL','JPua3rrs-8Sx',25,25,'[\"14088904-e218-4570-ae0b-26d4e5d0b0ba.xlsx\",\"dd03781d-599b-4857-9c75-9696599e06ad.docx\",\"1c2702b8-93fe-4090-b353-8a2b30809994.jpeg\",\"38eeb146-40bf-44dc-b950-b983795ea466.jpeg\",\"ffff6cd6-86ff-49a5-8846-25eee527f454.jpeg\",\"5c82b1f9-ec95-472e-8c79-602bb2348f74.jpeg\",\"6499ab22-0ea9-46f4-ac89-cddb131ee9bb.jpeg\",\"6aee2853-a7c1-4cab-bfb3-b42c030b9858.jpeg\",\"ea1b60ef-0de7-4a44-9291-5bc93145dad5.jpeg\",\"af0a7c57-ad5e-46c9-83cd-197ac7bbe99c.jpeg\",\"49562910-c7fe-41f2-a06f-8c670e79cb7a.jpeg\",\"91f28ca9-6599-4bd4-b6d1-83d2d71d65c7.jpeg\",\"081b6a6a-c824-49a7-82ee-f6eaaa114083.jpeg\",\"c2cfb6d6-eaa5-4cb5-b4e2-fd7ee7cbf8db.jpeg\",\"fbbf88b9-a6ca-49ef-af89-ec43a65a8aad.jpeg\",\"f317112f-9f04-4452-8314-a2983cd09db5.jpeg\",\"a4655db7-355e-43be-9f2d-2686cf0bdda9.jpeg\",\"ab81e06b-b19e-47e3-be4c-0f7ce5412a56.jpeg\",\"4bf3cb