INSERT INTO `Tickets` VALUES (31,'Solución de emergencia sobre problemas en la migración de la data desde STP al app repartidor.','<p><strong>Solución&nbsp;de&nbsp;emergencia&nbsp;sobre&nbsp;problemas&nbsp;en&nbsp;la&nbsp;migración&nbsp;de&nbsp;la&nbsp;data&nbsp;desde&nbsp;STP&nbsp;al&nbsp;app&nbsp;repartidor</strong>&nbsp;</p>','[\"Pablo Cifuentes\"]',9,'[]','2025-12-05',NULL,NULL,'T6X7o-r6QAib',NULL,9,9,'[]','[]',0,'Cerrado','2025-12-26','<p>Proceso&nbsp;solicitado</p>',NULL,'Alta','Web','pcifuentes@siroe.cl',NULL,'[]',NULL,3,'2025-12-18 21:25:28','2025-12-26 15:16:09'),(53,'Cambiar logo','<p>Cambiar&nbsp;logo&nbsp;de&nbsp;sidemenu<strong>&nbsp;(cambio&nbsp;de&nbsp;alcance)</strong></p>','[\"Maximiliano Aros\"]',8,'[]','2025-12-22',NULL,NULL,'PqJykjcZDtXa',NULL,8,8,'[]','[]',0,'Abierto',NULL,NULL,NULL,'Media','Web','maros@soportesiroe.cl',NULL,'[]',NULL,NULL,'2025-12-22 16:01:31','2025-12-26 12:59:12'),(54,'Editar fecha de recepcion','<p>Se&nbsp;debe&nbsp;poder&nbsp;editar&nbsp;la&nbsp;fecha&nbsp;de&nbsp;recepcion&nbsp;<strong>(Cambio&nbsp;de&nbsp;alcance)</strong></p>','[\"Maximiliano Aros\"]',8,'[]','2025-12-22',NULL,NULL,'PqJykjcZDtXa',NULL,8,8,'[]','[]',0,'Abierto',NULL,NULL,NULL,'Media','Web','maros@soportesiroe.cl',NULL,'[]',NULL,NULL,'2025-12-22 16:02:11','2025-12-26 13:26:33'),(55,'Escaneo de QR','<p>Al&nbsp;escanear&nbsp;QR&nbsp;cuando&nbsp;el&nbsp;corte&nbsp;ingresa&nbsp;al&nbsp;reactor,&nbsp;en&nbsp;app&nbsp;muestra&nbsp;procesado&nbsp;pero&nbsp;al&nbsp;ir&nbsp;a&nbsp;la&nbsp;pagina&nbsp;no&nbsp;se&nbsp;proceso.<strong>&nbsp;(bug)</strong></p><p></p>','[\"Maximiliano Aros\"]',8,'[]','2025-12-22',NULL,NULL,'PqJykjcZDtXa',NULL,8,10,'[]','[]',0,'Abierto',NULL,NULL,NULL,'Media','Web','maros@soportesiroe.cl',NULL,'[]',NULL,NULL,'2025-12-22 16:03:27','2025-12-26 15:47:01'),(56,'Boton descargar no funciona','<p>El&nbsp;boton&nbsp;de&nbsp;descargar&nbsp;no&nbsp;funciona<strong>&nbsp;</strong>(<strong>Considerar&nbsp;como&nbsp;bug)</strong></p>','[\"Maximiliano Aros\"]',8,'[]','2025-12-22',NULL,NULL,'PqJykjcZDtXa',NULL,8,8,'[]','[]',0,'Cerrado','2026-01-30','<p>Terminado</p>',NULL,'Media','Web','maros@soportesiroe.cl',NULL,'[]',NULL,NULL,'2025-12-22 16:03:55','2026-01-30 18:08:45'),(57,'Modificacion boton descargar','<p>El&nbsp;boton&nbsp;descargar&nbsp;debe&nbsp;descargar&nbsp;como&nbsp;excel,&nbsp;no&nbsp;como&nbsp;pdf<strong>&nbsp;(cambio&nbsp;de&nbsp;alcance)</strong></p>','[\"Maximiliano Aros\"]',8,'[]','2025-12-22',NULL,NULL,'PqJykjcZDtXa',NULL,8,8,'[]','[]',0,'Cerrado','2026-01-30','<p>Terminado</p>',NULL,'Media','Web','maros@soportesiroe.cl',NULL,'[]',NULL,NULL,'2025-12-22 16:04:39','2026-01-30 18:08:28'),(85,'No reconoce numero de matricula','<p>Al&nbsp;poner&nbsp;un&nbsp;numero&nbsp;de&nbsp;matricula&nbsp;existente&nbsp;en&nbsp;modulo&nbsp;cortes,&nbsp;no&nbsp;lo&nbsp;reconoce.<strong>&nbsp;(bug)</strong></p><p></p>','[\"Maximiliano Aros\"]',8,'[]','2025-12-26',NULL,NULL,'PqJykjcZDtXa',NULL,8,8,'[]','[]',0,'Cerrado','2026-01-30','<p>Terminado</p>',NULL,'Media','Web','maros@soportesiroe.cl',NULL,'[]',NULL,NULL,'2025-12-26 15:34:59','2026-01-30 18:08:07'),(91,'Agregar Informacion de Agentix','<p><strong>Se&nbsp;requiere&nbsp;agregar&nbsp;informacion&nbsp;de&nbsp;agentix&nbsp;en&nbsp;cada&nbsp;sitio&nbsp;web&nbsp;de&nbsp;siroe,&nbsp;Siroe.AI,&nbsp;Siroe.cl,&nbsp;Siroe.pe,&nbsp;Soportesiroe.cl.</strong>&nbsp;</p>','[\"Maximiliano Aros\"]',8,'[]','2025-12-28',NULL,NULL,'LEXAqgpV6D5B',NULL,9,8,'[]','[]',0,'En espera',NULL,NULL,NULL,'Baja','Web','pcifuentes@siroe.cl',NULL,'[]',NULL,NULL,'2025-12-28 13:52:23','2026-01-30 18:09:17'),(92,'Cambios Ticketera Siroe','<ul><li>Eliminar&nbsp;estimación,&nbsp;ya&nbsp;que&nbsp;no&nbsp;siempre&nbsp;un&nbsp;ticket&nbsp;debe&nbsp;tener&nbsp;estimaciones,&nbsp;para&nbsp;eso&nbsp;esta&nbsp;la&nbsp;información&nbsp;del&nbsp;cierre.</li><li>Al&nbsp;momento&nbsp;de&nbsp;crear&nbsp;un&nbsp;ticket&nbsp;el&nbsp;estado&nbsp;si&nbsp;o&nbsp;si&nbsp;es&nbsp;&quot;nuevo&quot;&nbsp;por&nbsp;ende&nbsp;no&nbsp;deberia&nbsp;poder&nbsp;cambiarse.</li><li>Al&nbsp;momento&nbsp;de&nbsp;hacer&nbsp;click&nbsp;debería&nbsp;pasar&nbsp;automaticamente&nbsp;a&nbsp;&quot;Abierto&quot;,&nbsp;el&nbsp;resto&nbsp;de&nbsp;estado&nbsp;se&nbsp;pueden&nbsp;cambiar.</li><li>La&nbsp;fecha&nbsp;de&nbsp;ingreso&nbsp;deberia&nbsp;estar&nbsp;fija&nbsp;tambien&nbsp;y&nbsp;no&nbsp;poder&nbsp;cambiarla.</li><li>El&nbsp;tecnico&nbsp;asignado&nbsp;se&nbsp;deberia&nbsp;poder&nbsp;seleccionar&nbsp;al&nbsp;momento&nbsp;de&nbsp;crear&nbsp;el&nbsp;ticket&nbsp;y&nbsp;que&nbsp;sea&nbsp;opcional.</li></ul><p></p><p></p>','[\"Maximiliano Aros\"]',8,'[]','2025-12-28',NULL,NULL,'LEXAqgpV6D5B',NULL,9,8,'[]','[]',0,'Cerrado','2025-12-29','<p>Se&nbsp;resuelven&nbsp;todas&nbsp;las&nbsp;peticiones&nbsp;con&nbsp;exito</p>',NULL,'Media','Web','pcifuentes@siroe.cl',NULL,'[]',NULL,2,'2025-12-28 13:56:43','2025-12-29 14:06:46'),(93,'Desarrollo Web de Tic Service','<p>Diseñar&nbsp;el&nbsp;nuevo&nbsp;sitio&nbsp;web&nbsp;de&nbsp;tic&nbsp;con&nbsp;la&nbsp;idea&nbsp;de&nbsp;SPdigital,&nbsp;luego&nbsp;entregarlo&nbsp;para&nbsp;el&nbsp;desarrollo&nbsp;de&nbsp;este&nbsp;diseño&nbsp;en&nbsp;un&nbsp;wordpress.</p>','[\"Maximiliano Aros\"]',8,'[]','2025-12-28',NULL,NULL,'1SnK_jY2TlwM',NULL,9,8,'[]','[]',0,'Cerrado','2026-01-20','<p>Ya&nbsp;se&nbsp;realizo&nbsp;diseno&nbsp;de&nbsp;pagina&nbsp;de&nbsp;tic&nbsp;online,&nbsp;comparto&nbsp;link&nbsp;de&nbsp;figma&nbsp;<strong><a href=\"https://www.figma.com/design/GE1jIYFfGWbpw47fpM6uj4/Tic-Online-Store?node-id=22-2&amp;t=4fZqFxtlIhVxV1Xq-0\" rel=\"noopener noreferrer\" target=\"_blank\">https://www.figma.com/design/GE1jIYFfGWbpw47fpM6uj4/Tic-Online-Store?node-id=22-2&amp;t=4fZqFxtlIhVxV1Xq-0</a></strong></p>',NULL,'Media','Web','pcifuentes@siroe.cl',NULL,'[]',NULL,NULL,'2025-12-28 13:58:05','2026-01-20 18:02:17'),(104,'RE: AVISO DE VENCIMIENTO ABASTIBLE / FEDERACION DE ASOCIACIONES DE FUNCIONARIOS DE LA SALUD FENATS SERVICIO DE SALUD / 0010645626','Estimado Javier,\n\nTicket 